function inMallEntrance(p){return p.x>=245&&p.x<=455&&p.y>=240&&p.y<=390}
function inMallExit(p){return p.x>=50&&p.x<=250&&p.y>=290&&p.y<=505}
function worldWidthForRoomScene(code,scene){return isPublicRoomCode(code)&&scene==="mall"?MALL_WORLD_W:WORLD_W}
function closeEnough(p,rect,maxDist){
 const x=clamp(p.x,rect.x,rect.x+rect.w),y=clamp(p.y,rect.y,rect.y+rect.h);
 return Math.hypot(p.x-x,p.y-y)<=maxDist;
}

